---@class TrailButtonGroupNode
local TrailButtonGroupNode = Class('TrailButtonGroupNode')

function TrailButtonGroupNode:__init()
    self.startButton = nil
    self.segmentDownButton = nil
    self.segmentStayButton = nil
    self.segmentUpButton = nil
    self.cb = nil
    self.buttons = nil
end

function TrailButtonGroupNode:__delete()
    self.buttons = nil
    self.startButton = nil
    self.segmentDownButton = nil
    self.segmentStayButton = nil
    self.segmentUpButton = nil
    self.cb = nil
end

function TrailButtonGroupNode:Awake()
    trailBattleMgr = TrailBattleMgr:GetInstance()
    ---@type UnityEngine.Transform
    local transform = self.controller.transform
    self.startButton = transform:Find('StartButton')
    self.segmentDownButton = transform:Find('LevelDownButton')
    self.segmentStayButton = transform:Find('LevelEqButton')
    self.segmentUpButton = transform:Find('LevelUpButton')
    self.buttons = { self.startButton, self.segmentDownButton, self.segmentStayButton, self.segmentUpButton }
    UIEventProxy.Create(self.startButton.gameObject).onPointerClick = Bind(self, self.OnStartButtonAction)
    UIEventProxy.Create(self.segmentDownButton.gameObject).onPointerClick = Bind(self, self.OnDownButtonAction)
    UIEventProxy.Create(self.segmentStayButton.gameObject).onPointerClick = Bind(self, self.OnStayButtonAction)
    UIEventProxy.Create(self.segmentUpButton.gameObject).onPointerClick = Bind(self, self.OnUpButtonAction)
end

---SetCheckIndex
---设置当前选中状态
---@param index number 第几个按钮
function TrailButtonGroupNode:SetCheckIndex(index)
    local t = self.buttons
    for i = 1, #t do
        if KTool.IsActive(t[i].gameObject) then
            local transform = t[i]
            local checkImageTrans = transform:Find('CurImg')
            local textTrans = transform:Find('Text')
            if i == index then
                KTool.SetActive(textTrans.gameObject, false)
                KTool.SetActive(checkImageTrans.gameObject, true)
            else
                KTool.SetActive(textTrans.gameObject, true)
                KTool.SetActive(checkImageTrans.gameObject, false)
            end
        end
    end
end

---IsActive
---是否是显示的某个类型
---@param tabIndex number
function TrailButtonGroupNode:IsActive(tabIndex)
    return KTool.IsActive(self.buttons[tabIndex].gameObject)
end

---OnStartButtonAction
---起始位置
---@param eventData UnityEngine.EventSystems.PointerEventData
function TrailButtonGroupNode:OnStartButtonAction(eventData)
    self:SetCheckIndex(TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON)
    if self.cb then
        self.cb(TrailBattleMgr.CONSTANTS.BUTTON_GROUP_ACTION.START_BUTTON)
    end
end

