---FreshButtonGroup
---@param enterDojo TrailEnterDojo
function TrailButtonGroupNode:FreshButtonGroup(enterDojo, cb)
    self.cb = nil
    self.cb = cb
    local segmentVo = trailBattleMgr:GetSegmentRewardVoByRefId(enterDojo.segment)
    KTool.SetActive(self.segmentUpButton.gameObject, segmentVo.upGrade ~= 0)
    KTool.SetActive(self.segmentStayButton.gameObject, segmentVo.keepGrade ~= 0)
    KTool.SetActive(self.segmentDownButton.gameObject, segmentVo.downGrade ~= 0)
end

---MoveToMySegmentGroup
---定位到我当前所在的定位组
---@param enterDojo TrailEnterDojo
function TrailButtonGroupNode:MoveToMySegmentGroup(enterDojo, disableStart)
    if not isNull(disableStart) then
        KTool.SetActive(self.startButton.gameObject, not checkBool(disableStart))
    end
    local _, group = trailBattleMgr:GetRankGroupBySegment(enterDojo.segment)
    self:SetCheckIndex(group)
    return group
end

function TrailButtonGroupNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return TrailButtonGroupNode